# Real bounded controls for staged workload-drain-helper-v1.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$DrainHelperPath,
  [Parameter(Mandatory)][string]$DrainHelperSha256,
  [Parameter(Mandatory)][string]$OutputPath,
  [Parameter(Mandatory)][string]$WorkRoot
)
$ErrorActionPreference='Stop';$sha='^[0-9a-fA-F]{64}$';if($DrainHelperSha256 -notmatch $sha){throw 'drain helper SHA-256 required'}
$helper=[IO.Path]::GetFullPath($DrainHelperPath);if(-not(Test-Path -LiteralPath $helper -PathType Leaf)){throw 'drain helper missing'};$item=Get-Item -LiteralPath $helper -Force;if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or $item.Length -gt 131072){throw 'drain helper bounds/reparse gate failed'};if((Get-FileHash -LiteralPath $helper -Algorithm SHA256).Hash.ToLowerInvariant() -cne $DrainHelperSha256.ToLowerInvariant()){throw 'drain helper hash mismatch'};. $helper
if(-not(Test-Path -LiteralPath $WorkRoot)){[IO.Directory]::CreateDirectory($WorkRoot)|Out-Null}
$powershell=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe';$outputFull=[IO.Path]::GetFullPath($OutputPath)
function Quote-DrainArg([string]$Value){if($Value -notmatch '[\s"]'){return $Value};return '"'+$Value.Replace('"','\"')+'"'}
function Write-FreshText([string]$Path,[string]$Text){$full=[IO.Path]::GetFullPath($Path);if(Test-Path -LiteralPath $full){throw "fresh control file required: $full"};$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$full.$PID.$([guid]::NewGuid().ToString('N')).tmp";$s=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$b=[Text.Encoding]::UTF8.GetBytes($Text);$s.Write($b,0,$b.Length);$s.Flush($true)}finally{$s.Dispose()};[IO.File]::Move($tmp,$full)}
function Publish-Failure([object]$Record,[string]$Message){$parent=Split-Path -Parent $outputFull;if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};if(Test-Path -LiteralPath $outputFull){throw 'failure receipt must be fresh'};$value=[ordered]@{kind='sr0-display-workload-drain-controls-r9';status='held';failure=$Message;helperSha256=$DrainHelperSha256.ToLowerInvariant();failedCase=$Record;nativeQualificationClaim=$false};Write-FreshText $outputFull (($value|ConvertTo-Json -Depth 18)+"`r`n")}
function Invoke-DrainCase([string]$Name,[string]$FilePath,[string[]]$Arguments,[int]$ExpectedExit,[int]$TimeoutSeconds,[bool]$ExpectTerminal,[bool]$ExpectInheritedPipeDelay){
  $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$FilePath;$psi.Arguments=(($Arguments|ForEach-Object{Quote-DrainArg ([string]$_)}) -join ' ');$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=$null;$out=$null;$err=$null;$proof=$null;$caseError=$null;$cleanupError=$null
  try{$p=[Diagnostics.Process]::Start($psi);if($null -eq $p){throw 'control child did not start'};$h=$p.Handle;if($h -eq [IntPtr]::Zero){throw 'control child handle null'};$out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync();$proof=Complete-WorkloadDrainV1 -Process $p -StdoutTask $out -StderrTask $err -TimeoutSeconds $TimeoutSeconds;if($ExpectTerminal -and (-not $proof.processWaitCompleted -or -not $proof.processTerminal -or -not $proof.streamsDrained)){throw "drain case failed: $Name"};if(-not $ExpectTerminal -and ($proof.processTerminal -or $proof.processWaitCompleted)){throw "nonterminal control unexpectedly completed: $Name"};if($proof.elapsedMilliseconds -gt ($TimeoutSeconds*1000+1000) -or -not $proof.totalBudgetBounded){throw "drain total budget exceeded: $Name"};if($ExpectTerminal -and [int]$p.ExitCode -ne $ExpectedExit){throw "drain exit mismatch: $Name"}}catch{$caseError=$_.Exception.Message}finally{if($p){try{if(-not $p.HasExited){$p.Kill()};[void]$p.WaitForExit(5000)}catch{$cleanupError=$_.Exception.Message}}}
  $stdoutText=if($out -and $out.IsCompleted){$out.GetAwaiter().GetResult()}else{'<stdout-drain-timeout>'};$stderrText=if($err -and $err.IsCompleted){$err.GetAwaiter().GetResult()}else{'<stderr-drain-timeout>'};$record=[ordered]@{name=$Name;file=$FilePath;argv=$psi.Arguments;exit=if($p -and $p.HasExited){[int]$p.ExitCode}else{$null};expectedExit=$ExpectedExit;expectTerminal=$ExpectTerminal;expectInheritedPipeDelay=$ExpectInheritedPipeDelay;proof=$proof;stdout=$stdoutText;stderr=$stderrText;cleanupError=$cleanupError;failure=$caseError};if($caseError){Publish-Failure $record $caseError;throw $caseError};return $record
}
$cases=@();$cases+=Invoke-DrainCase 'exit-zero' $powershell @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command','Write-Output drain-zero; exit 0') 0 15 $true $false;$cases+=Invoke-DrainCase 'exit-natural-nonzero' $powershell @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command','Write-Output drain-nonzero; exit 17') 17 15 $true $false;$cases+=Invoke-DrainCase 'delayed-output' $powershell @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command','Start-Sleep -Milliseconds 750; [Console]::Out.Write("drain-delayed"); [Console]::Out.Flush(); exit 0') 0 15 $true $false
$childPath=Join-Path $WorkRoot 'inherited-pipe-child-r9.ps1';$launcherPath=Join-Path $WorkRoot 'inherited-pipe-launcher-r9.cmd';Write-FreshText $childPath "Start-Sleep -Seconds 2`r`nWrite-Output inherited-delay`r`n";$launcher=@('@echo off','start "" /b "'+$powershell+'" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$childPath+'"','echo parent-exit','exit /b 0') -join "`r`n";Write-FreshText $launcherPath ($launcher+"`r`n");$cases+=Invoke-DrainCase 'inherited-pipe-delay' (Join-Path $env:SystemRoot 'System32\cmd.exe') @('/d','/s','/c',$launcherPath) 0 15 $true $true
$cases+=Invoke-DrainCase 'nonterminal-timeout' $powershell @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command','Start-Sleep -Seconds 20') -1 1 $false $false
$out=[ordered]@{kind='sr0-display-workload-drain-controls-r9';status='passed-source-controls';helperSha256=$DrainHelperSha256.ToLowerInvariant();cases=$cases;controls=@('exit-zero','exit-natural-nonzero','delayed-output','inherited-pipe-delay','nonterminal-timeout');nativeQualificationClaim=$false};Write-FreshText $outputFull (($out|ConvertTo-Json -Depth 18)+"`r`n");$out|ConvertTo-Json -Depth 8;exit 0
